<template><section class="reviews"><header><div><span>COMMUNITY NOTES</span><h3>Reviews</h3></div><strong v-if="data.review_count">★ {{ data.average_rating }} <small>{{ data.review_count }} reviews</small></strong></header><p v-if="loading" class="empty">Loading reviews…</p><p v-else-if="!data.review_count" class="empty">No reviews yet. Be the first to leave a useful note.</p><article v-for="review in data.reviews" :key="review.id"><div class="stars">{{ '★'.repeat(review.rating) }}{{ '☆'.repeat(5-review.rating) }} <span>{{ review.reviewer_name }}</span><em v-if="review.verified_purchase">Verified purchase</em></div><h4 v-if="review.title">{{ review.title }}</h4><p>{{ review.comment }}</p><blockquote v-if="review.merchant_reply"><strong>BeCool replied</strong>{{ review.merchant_reply }}</blockquote></article><router-link v-if="!isAuthenticated" :to="{path:'/login',query:{redirect:route.fullPath}}" class="write">Sign in to write a review</router-link><form v-else @submit.prevent="submit"><div class="form-head"><h4>Write a review</h4><label>Rating<select v-model.number="form.rating"><option v-for="n in 5" :key="n" :value="n">{{ n }} stars</option></select></label></div><input v-model.trim="form.title" maxlength="120" placeholder="Review title"><textarea v-model.trim="form.comment" maxlength="2000" placeholder="What should another shopper know?"></textarea><p v-if="message" :class="{error}">{{ message }}</p><button :disabled="pending">{{ pending?'Publishing…':'Publish review' }}</button></form></section></template>
<script setup>
import { onMounted,reactive,ref } from 'vue';import { useRoute } from 'vue-router';import { getProductReviews,submitProductReview } from '../../api';import { useAuth } from '../../composables/useAuth'
const props=defineProps({productId:{type:Number,required:true}}),route=useRoute(),{isAuthenticated}=useAuth(),data=ref({average_rating:0,review_count:0,reviews:[]}),loading=ref(true),pending=ref(false),message=ref(''),error=ref(false),form=reactive({rating:5,title:'',comment:''})
async function load(){loading.value=true;try{data.value=(await getProductReviews(props.productId)).data}catch{}finally{loading.value=false}}async function submit(){pending.value=true;message.value='';error.value=false;try{await submitProductReview(props.productId,{...form});message.value='Thank you. Your review is awaiting moderation.';Object.assign(form,{rating:5,title:'',comment:''});await load()}catch(e){error.value=true;message.value=e.response?.data?.detail||'Could not publish your review.'}finally{pending.value=false}}onMounted(load)
</script>
<style scoped>.reviews{padding:1rem 0}.reviews>header{display:flex;justify-content:space-between;align-items:end}.reviews header span{font-size:.6rem;font-weight:900;letter-spacing:.16em;color:#738079}.reviews h3{margin:.25rem 0;font:700 1.55rem Georgia,serif}.reviews header>strong{font:700 1.25rem Georgia,serif}.reviews header small{display:block;color:#718078;font:500 .65rem sans-serif}.empty{padding:2rem;border-radius:1rem;background:#fffdf8;color:#6e7b75;text-align:center;font-size:.78rem}.reviews>article{padding:1rem 0;border-bottom:1px solid #e7eae3}.stars{color:#9aaa48;font-size:.8rem}.stars span{margin-left:.6rem;color:#173f34;font-weight:800}.stars em{margin-left:.5rem;border-radius:999px;background:#e4f08a;padding:.2rem .4rem;color:#173f34;font-size:.55rem;font-style:normal}.reviews article h4{margin:.6rem 0 .25rem}.reviews article p{margin:.2rem 0;color:#617068;font-size:.78rem;line-height:1.55}.reviews blockquote{margin:.7rem 0 0;padding:.7rem;border-left:3px solid #dff263;background:#f3f5ec;color:#607069;font-size:.72rem}.reviews blockquote strong{display:block;color:#173f34}.write{display:inline-block;margin-top:1rem;color:#173f34;font-weight:850;text-decoration:underline}.reviews form{display:grid;gap:.65rem;margin-top:1.2rem;padding:1rem;border-radius:1rem;background:#fffdf8}.form-head{display:flex;justify-content:space-between;align-items:center}.form-head h4{margin:0;font:700 1.1rem Georgia,serif}.form-head label{font-size:.65rem}.reviews input,.reviews textarea,.reviews select{border:1px solid #d4dcd5;border-radius:.75rem;background:white;padding:.7rem;color:#173f34}.reviews textarea{min-height:6rem;resize:vertical}.reviews form button{justify-self:start;border:0;border-radius:999px;background:#173f34;padding:.7rem 1rem;color:white;font-weight:850}.reviews form p{font-size:.7rem;color:#47704d}.reviews form p.error{color:#9d3434}</style>
